/* @lc app=leetcode id=3377 lang=kotlin */ class Solution { fun minOperations(n: Int, m: Int): Int = (0..9999).map { x -> x >= 2 && (2..Math.sqrt(x.toDouble()).toInt()).none { x % it == 0 } }.let { pr -> if (pr[n] || pr[m]) -1 else n.toString().length.let { L -> IntArray(10000) { Int.MAX_VALUE }.also { it[n] = n }.let { d -> java.util.PriorityQueue<IntArray>(compareBy<IntArray> { it[0] }).also { it.add(intArrayOf(n, n)) }.let { pq -> generateSequence { pq.poll() }.filter { (c, u) -> c == d[u] }.forEach { (c, u) -> (0 until L).flatMap { p -> Math.pow(10.0, p.toDouble()).toInt().let { w -> (u / w % 10).let { dg -> listOfNotNull(if (dg < 9) u + w else null, if (dg > 0) u - w else null) } } }.filter { !pr[it] && c + it < d[it] }.forEach { v -> pq.add(intArrayOf(c + v, v)).also { d[v] = c + v } } }.let { d[m].let { if (it == Int.MAX_VALUE) -1 else it } } } } } } }